import{i as e,r as t,s as n,t as r}from"./app-DzHfMbrN.js";var i=JSON.parse(`{"path":"/Docs/grub_reference.html","title":"GRUB Scripts - Git remote user build","lang":"en-US","frontmatter":{},"git":{"updatedTime":1787181395000,"contributors":[{"name":"PETER HAUMER","username":"","email":"phaumer@us.ibm.com","commits":1},{"name":"phaumer","username":"phaumer","email":"4391934+phaumer@users.noreply.github.com","commits":1,"url":"https://github.com/phaumer"},{"name":"Esther M","username":"","email":"Esther.M@ibm.com","commits":1}],"changelog":[{"hash":"899900ddae61e77b30b53411518d800710133788","time":1787181395000,"email":"phaumer@us.ibm.com","author":"PETER HAUMER","message":"User Build v2 user guide and GRUB reference (#633)","coAuthors":[{"name":"Peter Haumer","email":"4391934+phaumer@users.noreply.github.com"},{"name":"Esther M","email":"Esther.M@ibm.com"}]}]},"filePathRelative":"Docs/grub_reference.md"}`),a={name:`grub_reference.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="grub-scripts-git-remote-user-build" tabindex="-1"><a class="header-anchor" href="#grub-scripts-git-remote-user-build"><span>GRUB Scripts - Git remote user build</span></a></h1><p>Version 2.0.0</p><p>Modular build automation system for remote z/OS® development environments.</p><h2 id="quick-start" tabindex="-1"><a class="header-anchor" href="#quick-start"><span>Quick start</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Sync code and build (SSH)</span></span>
<span class="line">grub_client prerequisites <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line">grub_client gitPush <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line">grub_client execute <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--command</span> <span class="token string">&quot;./build&quot;</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--files</span> <span class="token string">&quot;*.log&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Sync code and build (RSE API)</span></span>
<span class="line">grub_client prerequisites <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line">grub_client execute <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--command</span> <span class="token string">&quot;./build&quot;</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--files</span> <span class="token string">&quot;*.log&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="overview" tabindex="-1"><a class="header-anchor" href="#overview"><span>Overview</span></a></h2><p>GRUB provides six modular commands for z/OS development:</p><table><thead><tr><th>Command</th><th>Purpose</th><th>Transport</th></tr></thead><tbody><tr><td><strong>prerequisites</strong></td><td>Check requirements</td><td>SSH / RSE API</td></tr><tr><td><strong>gitPush</strong></td><td>Push changes by using the Git protocol</td><td>SSH only</td></tr><tr><td><strong>gitBundle</strong></td><td>Transfer files by using Git bundles</td><td>SSH / RSE API</td></tr><tr><td><strong>upload</strong></td><td>Upload files</td><td>SSH / RSE API</td></tr><tr><td><strong>execute</strong></td><td>Run commands</td><td>SSH / RSE API</td></tr><tr><td><strong>fetch</strong></td><td>Download files</td><td>SSH / RSE API</td></tr></tbody></table><p><strong>Key features:</strong></p><ul><li>✅ Dual transport support (SSH or RSE API through Zowe™)</li><li>✅ Delta bundles for efficient file transfers</li><li>✅ Git server clone support</li><li>✅ Automatic EBCDIC and UTF-8 conversion</li><li>✅ Preserves of uncommitted local changes</li><li>✅ GLOB pattern support for file operations</li><li>✅ Absolute path support for fetch operations</li><li>✅ Language-agnostic operation</li></ul><h2 id="installation" tabindex="-1"><a class="header-anchor" href="#installation"><span>Installation</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Option 1: Add to PATH (recommended)</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable"><span class="token environment constant">PATH</span></span><span class="token operator">=</span><span class="token string">&quot;/path/to/grub-scripts/bin:<span class="token environment constant">$PATH</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Option 2: Copy to a directory in your PATH</span></span>
<span class="line"><span class="token function">cp</span> bin/grub_client /usr/local/bin/</span>
<span class="line"><span class="token function">cp</span> bin/grub_server /usr/local/bin/</span>
<span class="line"><span class="token function">chmod</span> +x /usr/local/bin/grub_*</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Option 3: For Z Open Editor integration</span></span>
<span class="line"><span class="token function">mkdir</span> <span class="token parameter variable">-p</span> .zopeneditor/bin</span>
<span class="line"><span class="token function">cp</span> bin/grub_client .zopeneditor/bin/</span>
<span class="line"><span class="token function">cp</span> bin/grub_server .zopeneditor/bin/</span>
<span class="line"><span class="token function">chmod</span> +x .zopeneditor/bin/grub_*</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Verify installation</span></span>
<span class="line">grub_client <span class="token parameter variable">--version</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="prerequisites" tabindex="-1"><a class="header-anchor" href="#prerequisites"><span>Prerequisites</span></a></h2><h3 id="client-local-machine" tabindex="-1"><a class="header-anchor" href="#client-local-machine"><span>Client (local machine)</span></a></h3><p><strong>Required:</strong></p><ul><li>Git 2.0 or later</li><li>Bash shell</li></ul><p><strong>For SSH mode:</strong></p><ul><li>Password-less SSH configured</li></ul><p><strong>For RSE API mode:</strong></p><ul><li>Zowe CLI with the RSE API plugin installed</li><li>RSE API profile configured</li></ul><h3 id="server-z-os" tabindex="-1"><a class="header-anchor" href="#server-z-os"><span>Server (z/OS)</span></a></h3><p><strong>Required:</strong></p><ul><li>Git for z/OS</li></ul><p><strong>For SSH mode:</strong></p><ul><li>SSH server running</li></ul><p><strong>For RSE API mode:</strong></p><ul><li>RSE API service running</li></ul><h3 id="repository-setup" tabindex="-1"><a class="header-anchor" href="#repository-setup"><span>Repository setup</span></a></h3><p>Create <code>.gitattributes</code> file in the repository root:</p><div class="language-gitattributes line-numbers-mode" data-highlighter="prismjs" data-ext="gitattributes"><pre><code class="language-gitattributes"><span class="line"># EBCDIC source files</span>
<span class="line">*.c working-tree-encoding=IBM-1047</span>
<span class="line">*.h working-tree-encoding=IBM-1047</span>
<span class="line">*.cpp working-tree-encoding=IBM-1047</span>
<span class="line">*.cbl working-tree-encoding=IBM-1047</span>
<span class="line">*.pli working-tree-encoding=IBM-1047</span>
<span class="line">*.asm working-tree-encoding=IBM-1047</span>
<span class="line">*.jcl working-tree-encoding=IBM-1047</span>
<span class="line">Makefile working-tree-encoding=IBM-1047</span>
<span class="line"></span>
<span class="line"># Text files (terminal-compatible)</span>
<span class="line">*.json working-tree-encoding=ISO8859-1</span>
<span class="line">*.xml working-tree-encoding=ISO8859-1</span>
<span class="line">*.md working-tree-encoding=ISO8859-1</span>
<span class="line">*.txt working-tree-encoding=ISO8859-1</span>
<span class="line"></span>
<span class="line"># Binary files</span>
<span class="line">*.jar binary</span>
<span class="line">*.zip binary</span>
<span class="line">*.o binary</span>
<span class="line"></span>
<span class="line"># Alternative: IBM z/OS Git extension format (also supported)</span>
<span class="line"># *.c zos-working-tree-encoding=ibm-1047 git-encoding=utf-8</span>
<span class="line"># *.json zos-working-tree-encoding=utf-8 git-encoding=utf-8</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Pattern matching:</strong></p><ul><li>Supports both <code>working-tree-encoding=</code> and <code>zos-working-tree-encoding=</code> formats.</li><li>More specific patterns override wildcards patterns. The last matching pattern takes precedence.</li><li>Matches standard Git .gitattributes behavior.</li></ul><h2 id="commands" tabindex="-1"><a class="header-anchor" href="#commands"><span>Commands</span></a></h2><h3 id="_1-prerequisites" tabindex="-1"><a class="header-anchor" href="#_1-prerequisites"><span>1. Prerequisites</span></a></h3><p>Check that all requirements are met.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># SSH mode</span></span>
<span class="line">grub_client prerequisites <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># RSE API mode</span></span>
<span class="line">grub_client prerequisites <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-gitpush-ssh-only" tabindex="-1"><a class="header-anchor" href="#_2-gitpush-ssh-only"><span>2. gitPush (SSH only)</span></a></h3><p>Push changes by using the Git protocol.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Basic usage with hostname</span></span>
<span class="line">grub_client gitPush <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Using Git remote name (alternative to hostname)</span></span>
<span class="line">grub_client gitPush <span class="token parameter variable">--gitRemote</span> myremote <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># With Git server clone</span></span>
<span class="line">grub_client gitPush <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--gitServerRepository</span> git@github.com:user/repo.git</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Connection options:</strong></p><ul><li><code>--hostname user@server</code>: Uses an SSH hostname from ~/.ssh/config or a directly specified hostname.</li><li><code>--gitRemote name</code>: Uses an existing Git remote name as an alternative to hostname.</li></ul><p><strong>What it does:</strong></p><ol><li>Creates a temporary commit that contains all changes.</li><li>Pushes the changes to the remote repository through SSH.</li><li>Resets the temporary commit locally.</li><li>Initializes remote repository if necessary.</li></ol><p><strong>Git server clone:</strong></p><ul><li>Use <code>--gitServerRepository</code> to clone from a Git server during the initial synchronization.</li><li>Subsequent synchronizations use delta transfers for improved performance.</li><li>Works with GitHub, GitLab, Bitbucket, etc.</li></ul><h3 id="_3-gitbundle-ssh-or-rse-api" tabindex="-1"><a class="header-anchor" href="#_3-gitbundle-ssh-or-rse-api"><span>3. gitBundle (SSH or RSE API)</span></a></h3><p>Transfer changes by using Git bundles.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># RSE API mode</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># SSH mode with hostname</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># SSH mode with Git remote</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--gitRemote</span> myremote <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># With Git server clone</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--gitServerRepository</span> git@github.com:user/repo.git</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>What it does:</strong></p><ol><li><p>Creates a temporary commit that contains all changes.</p></li><li><p>Creates a delta bundle that only changes since last synchronization.</p></li><li><p>Uploads the bundle through SSH or RSE API.</p></li><li><p>Applies the bundle on the remote system.</p></li><li><p>Resets the temporary commit locally.</p></li></ol><h3 id="_4-upload" tabindex="-1"><a class="header-anchor" href="#_4-upload"><span>4. Upload</span></a></h3><p>Upload non-Git, such as dependency files and configuration files.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Upload a single file</span></span>
<span class="line">grub_client upload <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project <span class="token parameter variable">--files</span> <span class="token string">&quot;config.json&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Upload multiple files or folders</span></span>
<span class="line">grub_client upload <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project <span class="token parameter variable">--files</span> <span class="token string">&quot;resources data.txt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Upload by using GLOB patterns (preserves the directory hierarchy)</span></span>
<span class="line">grub_client upload <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--baseDir</span> ./myproject <span class="token parameter variable">--files</span> <span class="token string">&quot;**/*.c **/*.h&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Upload all headers files from system include directory</span></span>
<span class="line">grub_client upload <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/include <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--baseDir</span> /usr/include <span class="token parameter variable">--files</span> <span class="token string">&quot;**/*.h&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Features:</strong></p><ul><li>Supports files and directories.</li><li>Preserves the directory structure relative to <code>--baseDir</code>.</li><li>Creates remote directories automatically.</li><li>Applies encoding settings from .gitattributes automatically.</li><li><strong>GLOB pattern support:</strong><ul><li><code>*.ext</code> - All files with the specified extension in the current directory</li><li><code>**/*.ext</code> - Recursive search in all subdirectories</li><li><code>dir/**/*.ext</code> - Recursive search in a specific directory</li><li><code>?</code> - Single character wildcard</li></ul></li></ul><p><strong>GLOB pattern examples:</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Upload all C source files recursively</span></span>
<span class="line"><span class="token parameter variable">--files</span> <span class="token string">&quot;**/*.c&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Upload headers files and source files</span></span>
<span class="line"><span class="token parameter variable">--files</span> <span class="token string">&quot;**/*.h **/*.c&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Upload files from a specific subdirectory</span></span>
<span class="line"><span class="token parameter variable">--files</span> <span class="token string">&quot;src/**/*.plx&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-execute" tabindex="-1"><a class="header-anchor" href="#_5-execute"><span>5. Execute</span></a></h3><p>Runs commands on a remote system.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Simple command</span></span>
<span class="line">grub_client execute <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--command</span> <span class="token string">&quot;pwd&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Build command</span></span>
<span class="line">grub_client execute <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--command</span> <span class="token string">&quot;./build&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Chained commands</span></span>
<span class="line">grub_client execute <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--command</span> <span class="token string">&quot;make clean &amp;&amp; make all&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-fetch" tabindex="-1"><a class="header-anchor" href="#_6-fetch"><span>6. Fetch</span></a></h3><p>Download files from a remote system.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Download a single file</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--files</span> <span class="token string">&quot;build.log&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Download files by using wildcard patterns</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--files</span> <span class="token string">&quot;*.log *.err&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Custom local directory</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--files</span> <span class="token string">&quot;build.log&quot;</span> <span class="token parameter variable">--localDir</span> ./build-logs</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Fetch files from an absolute path (no --remoteWorkspace required)</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--absolutePath</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--files</span> <span class="token string">&quot;/var/log/app.log&quot;</span> <span class="token parameter variable">--localDir</span> ./logs</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Fetch multiple files from an absolute path by using wildcards</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--absolutePath</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--files</span> <span class="token string">&quot;/var/log/*.log&quot;</span> <span class="token parameter variable">--localDir</span> ./logs</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Features:</strong></p><ul><li>Supports wildcard patterns (expanded on the remote system)</li><li>Automatic EBCDIC-to-UTF-8 conversion (SSH mode)</li><li>Default local directory: <code>./logs</code></li><li><strong>Absolute path support:</strong> Use <code>--absolutePath</code> option to fetch files from any absolute path without specifying <code>--remoteWorkspace</code></li></ul><p><strong>Absolute path examples:</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Fetch system logs</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--absolutePath</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--files</span> <span class="token string">&quot;/var/log/syslog /var/log/messages&quot;</span> <span class="token parameter variable">--localDir</span> ./system-logs</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Fetch files by using wildcards patterns</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--absolutePath</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--files</span> <span class="token string">&quot;/u/ibmuser/*.log&quot;</span> <span class="token parameter variable">--localDir</span> ./logs</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="transport-modes" tabindex="-1"><a class="header-anchor" href="#transport-modes"><span>Transport modes</span></a></h2><h3 id="ssh-mode" tabindex="-1"><a class="header-anchor" href="#ssh-mode"><span>SSH mode</span></a></h3><p><strong>Setup:</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Configure SSH</span></span>
<span class="line"><span class="token function">cat</span> <span class="token operator">&gt;&gt;</span> ~/.ssh/config <span class="token operator">&lt;&lt;</span> <span class="token string">EOF</span>
<span class="line">Host myserver</span>
<span class="line">    HostName zos.example.com</span>
<span class="line">    User myusername</span>
<span class="line">    IdentityFile ~/.ssh/id_rsa</span>
<span class="line">EOF</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Copy SSH key</span></span>
<span class="line">ssh-copy-id myserver</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Test</span></span>
<span class="line"><span class="token function">ssh</span> myserver <span class="token string">&quot;echo connected&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Usage:</strong> <code>--hostname user@myserver</code></p><p><strong>Supported commands:</strong> All six commands</p><h3 id="rse-api-mode" tabindex="-1"><a class="header-anchor" href="#rse-api-mode"><span>RSE API mode</span></a></h3><p><strong>Setup:</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Install Zowe CLI</span></span>
<span class="line"><span class="token function">npm</span> <span class="token function">install</span> <span class="token parameter variable">-g</span> @zowe/cli@latest</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Install RSE API plugin</span></span>
<span class="line">zowe plugins <span class="token function">install</span> @zowe/rse-api-for-zowe-cli@latest</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Create profile</span></span>
<span class="line">zowe profiles create rseapi-profile myprofile <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--host</span> zos.example.com <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--port</span> <span class="token number">6800</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--user</span> myusername <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--password</span> mypassword</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Test</span></span>
<span class="line">zowe rse-api-for-zowe-cli issue unix <span class="token string">&quot;echo test&quot;</span> <span class="token parameter variable">--cwd</span> <span class="token string">&quot;/&quot;</span> --rse-profile myprofile</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Usage:</strong> <code>--zoweProfile myprofile</code></p><p><strong>Supported commands:</strong> All commands except gitPush (use gitBundle instead)</p><h2 id="complete-workflows" tabindex="-1"><a class="header-anchor" href="#complete-workflows"><span>Complete workflows</span></a></h2><h3 id="workflow-1-ssh-mode" tabindex="-1"><a class="header-anchor" href="#workflow-1-ssh-mode"><span>Workflow 1: SSH mode</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 1. Check prerequisites</span></span>
<span class="line">grub_client prerequisites <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. Sync code</span></span>
<span class="line">grub_client gitPush <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. Execute build</span></span>
<span class="line">grub_client execute <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--command</span> <span class="token string">&quot;./build&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 4. Fetch results</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--files</span> <span class="token string">&quot;*.log&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="workflow-2-rse-api-mode" tabindex="-1"><a class="header-anchor" href="#workflow-2-rse-api-mode"><span>Workflow 2: RSE API mode</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 1. Check prerequisites</span></span>
<span class="line">grub_client prerequisites <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. Sync code</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. Execute build</span></span>
<span class="line">grub_client execute <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--command</span> <span class="token string">&quot;./build&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 4. Fetch results</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/MyRepo <span class="token parameter variable">--files</span> <span class="token string">&quot;*.log&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="workflow-3-git-server-clone" tabindex="-1"><a class="header-anchor" href="#workflow-3-git-server-clone"><span>Workflow 3: Git server clone</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># First sync - clone from Git server</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--gitServerRepository</span> git@github.com:user/repo.git</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Execute build</span></span>
<span class="line">grub_client execute <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/repo <span class="token parameter variable">--command</span> <span class="token string">&quot;./build&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Subsequent syncs - use delta bundles (faster)</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">--gitServerRepository</span> git@github.com:user/repo.git</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Fetch results</span></span>
<span class="line">grub_client fetch <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project/repo <span class="token parameter variable">--files</span> <span class="token string">&quot;*.log&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="encoding-setup" tabindex="-1"><a class="header-anchor" href="#encoding-setup"><span>Encoding setup</span></a></h2><h3 id="how-encoding-works" tabindex="-1"><a class="header-anchor" href="#how-encoding-works"><span>How encoding works</span></a></h3><ol><li><strong>On the Client</strong>: Files are stored in UTF-8.</li><li><strong>During transfer</strong>: The Git bundle contains a binary representation of the files.</li><li><strong>On z/OS</strong>: <code>grub_server</code> applies <code>chtag</code> based on <code>.gitattributes</code>.</li><li><strong>File tagging</strong>: Automatically applies <code>chtag</code> for IBM-1047, UTF-8, ISO8859-1.</li></ol><h3 id="encoding-recommendations" tabindex="-1"><a class="header-anchor" href="#encoding-recommendations"><span>Encoding recommendations</span></a></h3><p><strong>For z/OS source files (EBCDIC):</strong></p><ul><li>Use <code>IBM-1047</code> for C, C++, COBOL, PL/I, Assembler, JCL, and makefiles.</li><li>Required by z/OS compilers.</li></ul><p><strong>For text files viewable in a z/OS terminal:</strong></p><ul><li>Use <code>ISO8859-1</code> for JSON, XML, Markdown, and text files.</li><li>Compatible with UTF-8 tools and z/OS terminals.</li><li>Displays correctly in <code>cat</code>, <code>vi</code>, and SSH sessions.</li></ul><p><strong>Why ISO8859-1 instead of UTF-8?</strong></p><ul><li>UTF-8 files can appear garbled in z/OS EBCDIC terminals.</li><li>ISO8859-1 provides broad compatibility across tools and environments.</li></ul><h2 id="troubleshooting" tabindex="-1"><a class="header-anchor" href="#troubleshooting"><span>Troubleshooting</span></a></h2><h3 id="git-not-found" tabindex="-1"><a class="header-anchor" href="#git-not-found"><span>Git not found</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Check git</span></span>
<span class="line"><span class="token function">which</span> <span class="token function">git</span></span>
<span class="line"><span class="token function">git</span> <span class="token parameter variable">--version</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># On z/OS, add to ~/.profile</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable"><span class="token environment constant">PATH</span></span><span class="token operator">=</span><span class="token string">&quot;/usr/lpp/IBM/foz/v1r1/bin:<span class="token environment constant">$PATH</span>&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="ssh-connection-failed" tabindex="-1"><a class="header-anchor" href="#ssh-connection-failed"><span>SSH connection failed</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Test connection</span></span>
<span class="line"><span class="token function">ssh</span> myserver <span class="token string">&quot;echo connected&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Check config</span></span>
<span class="line"><span class="token function">cat</span> ~/.ssh/config</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Copy key</span></span>
<span class="line">ssh-copy-id myserver</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="zowe-profile-issues" tabindex="-1"><a class="header-anchor" href="#zowe-profile-issues"><span>Zowe profile issues</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># List profiles</span></span>
<span class="line">zowe profiles list rseapi</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Test profile</span></span>
<span class="line">zowe rse-api-for-zowe-cli issue unix <span class="token string">&quot;pwd&quot;</span> <span class="token parameter variable">--cwd</span> <span class="token string">&quot;/&quot;</span> --rse-profile myprofile</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="encoding-issues" tabindex="-1"><a class="header-anchor" href="#encoding-issues"><span>Encoding issues</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Check .gitattributes</span></span>
<span class="line"><span class="token function">cat</span> .gitattributes</span>
<span class="line"></span>
<span class="line"><span class="token comment"># On z/OS, check file tags</span></span>
<span class="line"><span class="token function">ls</span> <span class="token parameter variable">-T</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Manually tag a file</span></span>
<span class="line">chtag <span class="token parameter variable">-tc</span> IBM-1047 myfile.c</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="gitbundle-verification-failed-ssh-mode" tabindex="-1"><a class="header-anchor" href="#gitbundle-verification-failed-ssh-mode"><span>gitBundle verification failed (SSH mode)</span></a></h3><p>If <code>gitBundle</code> works with RSE API but fails with SSH, try the following steps:</p><p><strong>1. Enable debug mode</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">grub_client gitBundle <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project <span class="token parameter variable">--debug</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>This command shows:</p><ul><li>Git version and location on z/OS</li><li>Bundle file size and encoding tag</li><li>Detailed error messages from <code>git bundle verify</code></li></ul><p><strong>2. Check bundle file transfer</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># After failed attempt, check if bundle exists on z/OS</span></span>
<span class="line"><span class="token function">ssh</span> user@myserver <span class="token string">&quot;ls -lT /tmp/grub_*.bundle&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Expected results:</span></span>
<span class="line"><span class="token comment"># - File exists</span></span>
<span class="line"><span class="token comment"># - Size matches local bundle</span></span>
<span class="line"><span class="token comment"># - Tag is &#39;b binary&#39; (not &#39;t text&#39;)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. Common causes &amp; solutions</strong></p><table><thead><tr><th>Issue</th><th>Symptom</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Bundle not binary</strong></td><td>Tag shows <code>t text</code></td><td>SCP might convert the file automatically. Use RSE API instead.</td></tr><tr><td><strong>Git not in PATH</strong></td><td>&quot;git: not found&quot;</td><td>Automatic resolution is attempted. See the following note.</td></tr><tr><td><strong>Corrupted transfer</strong></td><td>Size mismatch</td><td>Check the network connection and try a smaller change set.</td></tr><tr><td><strong>Git version</strong></td><td>&quot;unknown option&quot;</td><td>Update Git on z/OS. Git 2.x or later is required.</td></tr></tbody></table><p><strong>Note on Git PATH resolution:</strong> The server automatically searches for Git in common z/OS locations:</p><ul><li><code>/usr/lpp/IBM/foz/v1r1/bin</code> (zOpen Git)</li><li><code>/usr/local/zopen/usr/local/bin</code> (zOpen alternate location)</li><li><code>/usr/lpp/IBM/git/bin</code> (IBM Git)</li><li><code>/opt/freeware/bin</code> (Freeware)</li><li><code>/usr/local/bin</code> (Standard UNIX System Services location)</li></ul><p>If Git is not found, the error output shows &quot;Git location: git: not found&quot; Add Git to the <code>PATH</code> environment variable manually.</p><p><strong>4. Manual verification</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># On z/OS, verify the bundle manually</span></span>
<span class="line"><span class="token function">ssh</span> user@myserver <span class="token string">&quot;cd /u/user/project &amp;&amp; git bundle verify /tmp/grub_*.bundle&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># If this command succeeds but grub_client fails, the issue is likely related to PATH.</span></span>
<span class="line"><span class="token comment"># Add to ~/.profile on z/OS (adjust path as needed):</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable"><span class="token environment constant">PATH</span></span><span class="token operator">=</span><span class="token string">&quot;/usr/lpp/IBM/foz/v1r1/bin:<span class="token environment constant">$PATH</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Or, for the alternate zOpen location:</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable"><span class="token environment constant">PATH</span></span><span class="token operator">=</span><span class="token string">&quot;/usr/local/zopen/usr/local/bin:<span class="token environment constant">$PATH</span>&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>5. Workaround: Use RSE API</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># RSE API handles binary transfers better</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--zoweProfile</span> myprofile <span class="token parameter variable">--remoteWorkspace</span> /u/user/project</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>6. Preserve the bundle for analysis</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Keep the bundle file for manual inspection</span></span>
<span class="line">grub_client gitBundle <span class="token parameter variable">--hostname</span> user@myserver <span class="token parameter variable">--remoteWorkspace</span> /u/user/project --preserve-bundle</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Bundle location: /tmp/grub_&lt;user&gt;_&lt;repo&gt;.bundle</span></span>
<span class="line"><span class="token comment"># Manual Verification: git bundle verify /tmp/grub_*.bundle</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="common-options" tabindex="-1"><a class="header-anchor" href="#common-options"><span>Common options</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">-v, <span class="token parameter variable">--verbose</span>               <span class="token comment"># Enable verbose output</span></span>
<span class="line"><span class="token parameter variable">--debug</span>                     <span class="token comment"># Enable debug mode (set -x on client and server)</span></span>
<span class="line">--preserve-bundle           <span class="token comment"># Preserve bundle files for manual inspection</span></span>
<span class="line">-h, <span class="token parameter variable">--help</span>                  <span class="token comment"># Show help</span></span>
<span class="line"><span class="token parameter variable">--version</span>                   <span class="token comment"># Show version</span></span>
<span class="line"><span class="token parameter variable">--localWorkspace</span> <span class="token operator">&lt;</span>path<span class="token operator">&gt;</span>     <span class="token comment"># Local workspace (default: current directory)</span></span>
<span class="line"><span class="token parameter variable">--remoteWorkspace</span> <span class="token operator">&lt;</span>path<span class="token operator">&gt;</span>    <span class="token comment"># Remote workspace on z/OS (required for most commands)</span></span>
<span class="line"><span class="token parameter variable">--gitRemote</span> <span class="token operator">&lt;</span>name<span class="token operator">&gt;</span>          <span class="token comment"># Git remote name (alternative to --hostname for Git operations)</span></span>
<span class="line"><span class="token parameter variable">--gitServerRepository</span> <span class="token operator">&lt;</span>url<span class="token operator">&gt;</span> <span class="token comment"># Git server URL for cloning (for example, git@github.com:user/repo.git)</span></span>
<span class="line"><span class="token parameter variable">--files</span> <span class="token operator">&lt;</span>list<span class="token operator">&gt;</span>              <span class="token comment"># File list for upload or fetch (supports GLOB patterns)</span></span>
<span class="line"><span class="token parameter variable">--command</span> <span class="token operator">&lt;</span>cmd<span class="token operator">&gt;</span>             <span class="token comment"># Command for execute</span></span>
<span class="line"><span class="token parameter variable">--localDir</span> <span class="token operator">&lt;</span>path<span class="token operator">&gt;</span>           <span class="token comment"># Local directory for fetch (default: ./logs)</span></span>
<span class="line"><span class="token parameter variable">--baseDir</span> <span class="token operator">&lt;</span>path<span class="token operator">&gt;</span>            <span class="token comment"># Base directory for upload (preserves the hierarchy from this point)</span></span>
<span class="line"><span class="token parameter variable">--absolutePath</span>              <span class="token comment"># For fetch, allows absolute paths without --remoteWorkspace</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Debug options:</strong></p><ul><li><code>--debug</code>: Enables command tracing (<code>set -x</code>) on both the client and server and shows all commands that run.</li><li><code>--preserve-bundle</code>: Preserves bundle files in <code>/tmp</code> for manual testing. Useful with <code>--debug</code>.</li><li>These options can be used together or separately.</li></ul>`,127)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};